  const fill = { size: [1, 0, 1, 0] };
  const vlist = (gap, extra) => A({ layout: { kind: "list", gap: gap == null ? 8 : gap } }, extra || {});
  const hlist = (gap, extra) => A({ layout: { kind: "list", direction: "Horizontal", gap: gap == null ? 8 : gap, v_align: "Center" } }, extra || {});
  const grid = (cw, ch, gap, extra) => A({ layout: { kind: "grid", cell: [0, cw, 0, ch], gap: gap == null ? 8 : gap } }, extra || {});

  const txt = (name, text, o) => { o = o || {}; const ts = o.text_size || 14; return A({ class: "TextLabel", name, text, size: [1, 0, 0, Math.max(22, Math.round(ts * 1.35))], bg_t: 1, text_color: "text", font: "font", text_size: 14 }, o); };
  const muted = (name, text, o) => txt(name, text, A({ text_color: "muted", text_size: 13 }, o || {}));
  const head = (name, text, o) => { o = o || {}; const ts = o.text_size || 22; return txt(name, text, A({ font: "title_font", text_size: ts, size: [1, 0, 0, Math.max(30, Math.round(ts * 1.3))] }, o)); };
  const big = (name, text, o) => txt(name, text, A({ font: "title_font", text_size: 56, size: [0, 600, 0, 80], text_stroke: { color: "#000000", transparency: 0.5 } }, o || {}));
  const btn = (name, text, o) => { o = A({}, o || {}); const acts = [{ on: "hover", do: "hover_grow" }]; if (o.action) acts.push(A({ on: "click" }, o.action)); delete o.action; return A({ class: "TextButton", name, text, size: [0, 160, 0, 44], bg: "primary", text_color: "auto", font: "title_font", text_size: 16, corner: "radius", stroke: STROKE, actions: acts }, o); };
  const ghost = (name, text, o) => btn(name, text, A({ bg: "surface2", text_color: "text" }, o || {}));
  const danger = (name, text, o) => btn(name, text, A({ bg: "danger" }, o || {}));
  const success = (name, text, o) => btn(name, text, A({ bg: "success" }, o || {}));
  const frame = (name, o) => A({ class: "Frame", name, size: [0, 300, 0, 200], bg: "surface", corner: "radius", stroke: STROKE }, o || {});
